"""``content/_schema/llm-context.md``: one generated file with every installed element's schema
and examples, to paste into any LLM together with ``docs/LLM_AUTHORING_PROMPT.md``."""

from __future__ import annotations

import io
import json
from pathlib import Path

from ruamel.yaml import YAML

from ..elements.registry import ElementRegistry
from .models import CourseMeta, LessonFile, SubjectMeta, UnitMeta

HEADER = """# Element and file reference (generated)

Generated by `uv run ilp schema` from the installed elements. Do not edit; re-run the command
after adding or changing an element. Paste this file into an LLM together with
`docs/LLM_AUTHORING_PROMPT.md`.

## Files

Every level is a YAML file. Keys marked `?` are optional.

"""

FOOTER = """
## Notes for authors

- Every item has `type` and the fields below; `id` is optional but recommended (a unique slug
  inside the lesson). Unknown fields are errors.
- Fields marked `markdown` accept Markdown (bold, lists, fenced code, `$math$`); `markdown-inline`
  accepts inline Markdown only.
- `answer` indexes are 0-based. `___` in a `fill-blank` prompt is a blank; `answers` has one entry
  per blank (a string or a list of accepted alternatives).
- Validate with `uv run ilp validate <path>`; messages are `file:line: message`.
"""


def _yaml_dump(data: object) -> str:
    y = YAML()
    y.indent(mapping=2, sequence=4, offset=2)
    y.width = 100
    buf = io.StringIO()
    y.dump(data, buf)
    return buf.getvalue()


def _row(name: str, required: bool, kind: str, desc: str) -> str:
    opt = "" if required else "?"
    tail = f": {desc}" if desc else ""
    return f"- `{name}{opt}` ({kind}){tail}"


def _model_keys(model: type) -> str:
    schema = model.model_json_schema()
    required = set(schema.get("required", []))
    rows = []
    for name, prop in schema.get("properties", {}).items():
        t = prop.get("type") or (
            "/".join(str(a.get("type", "?")) for a in prop.get("anyOf", []))
            if "anyOf" in prop
            else "object"
        )
        desc = prop.get("description", "")
        rows.append(_row(name, name in required, t, desc))
    return "\n".join(rows)


def build_llm_context(registry: ElementRegistry) -> str:
    out = [HEADER]
    out.append("### subject.yaml\n\n" + _model_keys(SubjectMeta) + "\n")
    out.append("### course.yaml\n\n" + _model_keys(CourseMeta) + "\n")
    out.append("### unit.yaml\n\n" + _model_keys(UnitMeta) + "\n")
    out.append(
        "### <name>.lesson.yaml\n\n"
        + _model_keys(LessonFile)
        + "\n\nAn `arrange: auto` lesson supplies `source:` with `notes?` (markdown), `facts?` "
        "(list of `{term, definition, hint?}`) and `cloze?` (sentences with `{{answer}}` or "
        "`{{a|b}}` blanks); the platform generates the items. A manual lesson may include "
        "`- type: auto` (with `only?: [notes|facts|cloze]`) among its items to expand the source "
        "at that point.\n"
    )
    out.append("## Elements\n")
    for type_ in registry.types():
        m = registry.get(type_)
        assert m is not None
        graded = "ungraded" if not m.graded else ("self-graded" if m.self_graded else "graded")
        out.append(f"### `{m.type}` — {m.title} ({graded})\n")
        if m.description:
            out.append(m.description + "\n")
        required = m.schema.get("required", [])
        out.append("Fields:\n")
        for name, prop in m.schema.get("properties", {}).items():
            fmt = prop.get("x-format")
            t = prop.get("type") or (
                "oneOf" if "oneOf" in prop else "anyOf" if "anyOf" in prop else "any"
            )
            bits = [t]
            if fmt:
                bits.append(fmt)
            if "enum" in prop:
                bits.append("one of " + ", ".join(map(str, prop["enum"])))
            if "default" in prop:
                bits.append(f"default {json.dumps(prop['default'])}")
            desc = prop.get("description", "")
            out.append(_row(name, name in required, ", ".join(bits), desc))
        for key in ("anyOf", "oneOf"):
            if key in m.schema:
                alts = [", ".join(f"`{r}`" for r in a.get("required", [])) for a in m.schema[key]]
                out.append(f"- requires one of: {' | '.join(alts)}")
        out.append("")
        out.append(
            "Schema:\n\n```json\n" + json.dumps(m.schema, indent=2, ensure_ascii=False) + "\n```\n"
        )
        examples = m.examples()
        if examples:
            out.append("Examples:\n\n```yaml\nitems:\n" + _indent(_yaml_dump(examples)) + "```\n")
    out.append(FOOTER)
    return "\n".join(out)


def _indent(text: str, n: int = 2) -> str:
    pad = " " * n
    return "".join(pad + line if line.strip() else line for line in text.splitlines(keepends=True))


def write_llm_context(registry: ElementRegistry, out_dir: Path) -> Path:
    out_dir.mkdir(parents=True, exist_ok=True)
    path = out_dir / "llm-context.md"
    path.write_text(build_llm_context(registry), encoding="utf-8")
    return path
